<div class="d-flex justify-content-between align-items-center mb-4"><div><h4 class="fw-bold mb-1"><?php echo htmlspecialchars($requisition['title']); ?></h4><p class="text-muted mb-0">Temporary requisition discussion</p></div><a class="btn btn-outline-secondary" href="/ERP/public/requisition"><i class="bi bi-arrow-left me-1"></i>Back</a></div>
<?php if (!empty($_SESSION['requisition_flash'])): ?><div class="alert alert-info"><?php echo htmlspecialchars($_SESSION['requisition_flash']); unset($_SESSION['requisition_flash']); ?></div><?php endif; ?>
<div class="row g-4"><div class="col-lg-8"><div class="card shadow-sm border-0 mb-4"><div class="card-body"><h5 class="fw-bold mb-3">Requisition details</h5><div class="table-responsive"><table class="table table-bordered align-middle mb-0"><thead><tr><th style="width: 40%;">Field</th><th>Value</th></tr></thead><tbody><?php if (!empty($requisition['form_data'])): ?><?php foreach (($requisition['form_data'] ?? []) as $fieldKey => $field): ?><tr><th class="bg-light"><?php echo htmlspecialchars((string)($field['label'] ?? ucfirst(str_replace('_', ' ', (string)$fieldKey)))); ?></th><td><?php echo nl2br(htmlspecialchars((string)($field['value'] ?? ''))); ?></td></tr><?php endforeach; ?><?php else: ?><tr><td colspan="2" class="text-muted">No requisition form data has been saved for this request.</td></tr><?php endif; ?></tbody></table></div></div></div><div class="card shadow-sm border-0 mb-4"><div class="card-body"><h5 class="fw-bold mb-3">Requested items</h5><div class="table-responsive"><table class="table table-striped align-middle mb-0"><thead><tr><th>Item</th><th>Code</th><th>Unit</th><th>Qty Required</th><th>Qty to Purchase</th><th>Price</th><th>Value</th><th>Adjust</th></tr></thead><tbody><?php if (!empty($requisition['items'])): ?><?php foreach (($requisition['items'] ?? []) as $item): ?><tr><td><?php echo htmlspecialchars((string)($item['description'] ?? $item['item_name'] ?? 'Item')); ?></td><td><?php echo htmlspecialchars((string)($item['item_code'] ?? '')); ?></td><td><?php echo htmlspecialchars((string)($item['unit'] ?? '')); ?></td><td><?php echo number_format((float)($item['quantity_required'] ?? 0), 2); ?></td><td><?php echo number_format((float)($item['quantity_to_purchase'] ?? 0), 2); ?></td><td>₦<?php echo number_format((float)($item['price'] ?? 0), 2); ?></td><td>₦<?php echo number_format((float)($item['value'] ?? 0), 2); ?></td><td><form method="post" action="/ERP/public/requisition/item-adjust" class="d-flex flex-column gap-2"><input type="hidden" name="requisition_id" value="<?php echo (int)$requisition['id']; ?>"><input type="hidden" name="item_id" value="<?php echo (int)$item['id']; ?>"><div class="input-group input-group-sm"><input type="number" class="form-control" name="delta" value="1" min="0.01" step="0.01" aria-label="Quantity adjustment"><button class="btn btn-outline-success" type="submit" name="direction" value="increase">+</button><button class="btn btn-outline-danger" type="submit" name="direction" value="decrease">-</button></div><input type="text" class="form-control form-control-sm" name="reason" placeholder="Reason for change" maxlength="255"><small class="text-muted">Latest: <?php echo htmlspecialchars((string)($item['adjustments'][0]['user_name'] ?? 'No adjustments yet')); ?></small></form></td></tr><?php if (!empty($item['adjustments'])): ?><tr><td colspan="8" class="bg-light"><div class="small fw-semibold text-muted mb-2">Adjustment history</div><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>User</th><th>Previous</th><th>New</th><th>Delta</th><th>Reason</th><th>Date</th></tr></thead><tbody><?php foreach (($item['adjustments'] ?? []) as $adjustment): ?><tr><td><?php echo htmlspecialchars((string)($adjustment['user_name'] ?? 'Unknown')); ?></td><td><?php echo number_format((float)($adjustment['previous_value'] ?? 0), 2); ?></td><td><?php echo number_format((float)($adjustment['new_value'] ?? 0), 2); ?></td><td><?php echo number_format((float)($adjustment['delta'] ?? 0), 2); ?></td><td><?php echo htmlspecialchars((string)($adjustment['adjustment_reason'] ?? '—')); ?></td><td><?php echo htmlspecialchars((string)($adjustment['changed_at'] ?? '')); ?></td></tr><?php endforeach; ?></tbody></table></div></td></tr><?php endif; ?><?php endforeach; ?><?php else: ?><tr><td colspan="8" class="text-muted">No items were added to this requisition.</td></tr><?php endif; ?></tbody></table></div></div></div><div class="card shadow-sm border-0 mb-4"><div class="card-body"><h5 class="fw-bold mb-3">Tagged colleagues</h5><?php if (!empty($requisition['participants'])): ?><div class="d-flex flex-wrap gap-2"><?php foreach (($requisition['participants'] ?? []) as $participant): ?><span class="badge text-bg-primary-subtle border border-primary-subtle px-3 py-2"><?php echo htmlspecialchars((string)($participant['name'] ?? '')); ?><?php if (!empty($participant['email'])): ?> <small class="text-muted"><?php echo htmlspecialchars((string)$participant['email']); ?></small><?php endif; ?></span><?php endforeach; ?></div><?php else: ?><p class="text-muted mb-0">No colleagues have been tagged for this requisition.</p><?php endif; ?></div></div><div class="card shadow-sm border-0"><div class="card-body"><div class="d-flex justify-content-between mb-3"><h5 class="fw-bold mb-0">Discussion</h5><span class="badge <?php echo $requisition['status'] === 'pending' ? 'text-bg-warning' : 'text-bg-secondary'; ?>"><?php echo $requisition['status'] === 'pending' ? 'Open' : 'Closed'; ?></span></div><div id="requisitionMessages" class="border rounded p-3 mb-3" style="min-height: 240px; max-height: 480px; overflow-y: auto;"><?php foreach (($requisition['messages'] ?? []) as $message): ?><div class="mb-3"><strong><?php echo htmlspecialchars($message['author_name']); ?></strong><small class="text-muted ms-2"><?php echo htmlspecialchars($message['created_at']); ?></small><div><?php echo nl2br(htmlspecialchars($message['message'])); ?></div></div><?php endforeach; ?></div><?php if ($requisition['status'] === 'pending' && empty($requisition['chat_closed_at'])): ?><form method="post" action="/ERP/public/requisition/message" class="mb-3"><input type="hidden" name="requisition_id" value="<?php echo (int)$requisition['id']; ?>"><div class="input-group"><input class="form-control" name="message" maxlength="2000" placeholder="Write an update" required><button class="btn btn-primary" type="submit"><i class="bi bi-send me-1"></i>Send</button></div></form><div class="row g-2"><div class="col-md-6"><form method="post" action="/ERP/public/requisition/decision"><input type="hidden" name="requisition_id" value="<?php echo (int)$requisition['id']; ?>"><button class="btn btn-success w-100" name="decision" value="approved" type="submit" onclick="return confirm('Approve this requisition?');"><i class="bi bi-check-circle me-1"></i>Approve</button><button class="btn btn-outline-danger w-100 mt-2" name="decision" value="rejected" type="submit" onclick="return confirm('Reject this requisition?');"><i class="bi bi-x-circle me-1"></i>Reject</button></form></div><div class="col-md-6"><form method="post" action="/ERP/public/requisition/handoff"><input type="hidden" name="requisition_id" value="<?php echo (int)$requisition['id']; ?>"><label class="form-label" for="nextUser">Tag next colleague</label><select id="nextUser" class="form-select mb-2" name="next_user_id" required><option value="">Select colleague</option><?php foreach (($companyUsers ?? []) as $companyUser): ?><option value="<?php echo (int)$companyUser['id']; ?>"><?php echo htmlspecialchars($companyUser['name']); ?></option><?php endforeach; ?></select><input class="form-control mb-2" name="handoff_note" maxlength="500" placeholder="Optional handoff note"><button class="btn btn-outline-primary w-100" type="submit"><i class="bi bi-person-plus me-1"></i>Tag and hand off</button></form></div></div><?php else: ?><div class="alert alert-light border mb-0">This discussion is closed because the requisition has been fully treated.</div><?php endif; ?></div></div></div><div class="col-lg-4"><div class="card shadow-sm border-0"><div class="card-body"><h5 class="fw-bold mb-3">Tagged colleagues</h5><?php foreach (($requisition['participants'] ?? []) as $participant): ?><div class="border-bottom py-2"><strong><?php echo htmlspecialchars($participant['name']); ?></strong><div class="small text-muted"><?php echo htmlspecialchars($participant['email']); ?></div></div><?php endforeach; ?></div></div></div></div>
<?php if ($requisition['status'] === 'pending' && empty($requisition['chat_closed_at'])): ?><script>
(() => {
	const messageBox = document.getElementById('requisitionMessages');
	const endpoint = '/ERP/public/requisition/messages?id=<?php echo (int)$requisition['id']; ?>';
	let lastMessageId = <?php echo (int)(end($requisition['messages'])['id'] ?? 0); ?>;
	async function refreshMessages() {
		try {
			const response = await fetch(endpoint, {headers: {'Accept': 'application/json'}, cache: 'no-store'});
			if (!response.ok) return;
			const data = await response.json();
			if (!Array.isArray(data.messages) || !data.messages.length || Number(data.messages[data.messages.length - 1].id) === lastMessageId) return;
			messageBox.innerHTML = data.messages.map((message) => `<div class="mb-3"><strong>${escapeHtml(message.author_name)}</strong><small class="text-muted ms-2">${escapeHtml(message.created_at)}</small><div>${escapeHtml(message.message).replace(/\n/g, '<br>')}</div></div>`).join('');
			lastMessageId = Number(data.messages[data.messages.length - 1].id);
			messageBox.scrollTop = messageBox.scrollHeight;
		} catch (error) {}
	}
	function escapeHtml(value) { return String(value).replace(/[&<>'"]/g, (character) => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#039;', '"': '&quot;'}[character])); }
	window.setInterval(refreshMessages, 3000);
})();
</script><?php endif; ?>